%tag {
  a,
  button {
    @font mono mono;
    @space letter-spacing 0.3px >=ipad_portrait;
    background-color: #f7f5ed;
    text-transform: uppercase;
    display: flex;
    height: 30px;
    padding: 5px 13px 4px 13px;
    justify-content: center;
    align-items: center;
    gap: 10px;
    border-radius: 40px;
    border: none;
    transition:
      background-color 150ms ease,
      color 150ms ease !important;
    user-select: none;

    span {
      transition:
        transform 150ms ease,
        color 150ms ease !important;
    }

    &:hover {
      @responsive >=ipad_portrait {
        @color bg dark_grey;
        @color fg white;
      }
      span {
        transform: translateX(3px);
        transition:
          transform 150ms ease,
          color 0ms ease !important;
      }
    }

    &.active,
    &[data-active] {
      @color bg dark_grey;
      @color fg white;
      span {
        transform: translateX(3px);
        transition:
          transform 150ms ease,
          color 0ms ease !important;
      }
    }
  }
}

[b-tpl="tag cloud"] {
  @space container;
  @space! padding-top 0 $lg;
  @space! margin-top calc(var[block] * -1) $lg;

  .inner {
    @display flex;
    align-items: center;

    @responsive ipad_portrait {
      flex-direction: column;
      gap: 50px;
    }

    @responsive $mobile {
      flex-direction: column;
      gap: 50px;
    }

    > .tags {
      @display flex;
      @column 5/12 $lg;
      @column 12/12 ipad_portrait;
      @column 12/12 $mobile;
      justify-content: center;
      align-items: center;

      .tags-inner {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: center;
        @space width 400px $lg;
        @space width 400px ipad_portrait;
        @space gap 0.25em;
        @space gap 0.25em ipad_portrait;
        @space gap 0.25em $mobile;
        @extend %tag;

        button {
          position: relative;
          overflow: clip;

          &[data-active] {
            background-color: #000 !important;
          }

          &:hover {
            background-color: #000 !important;
          }

          span {
            z-index: 1;
            transform: translateX(0) !important;
          }

          .progress {
            z-index: 0;
            transform: scale(0, 1);
            transform-origin: 0% 50%;
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            transition: background-color 250ms ease;

            &.running {
              background-color: #18306d;
            }

            &.done {
              background-color: transparent;
            }
          }
        }
      }
    }

    > .cases {
      @column 7/12 $lg;
      @column 1/1 ipad_portrait;
      @space width 100% ipad_portrait;

      .canvas {
        display: grid;
        grid-template-areas: "stack";
        place-items: center;
        position: relative;
        display: none;
        height: 100%;

        @responsive $lg {
          aspect-ratio: 1/1;
        }

        @responsive ipad_portrait {
          @space padding-bottom 75px;
        }

        @responsive $mobile {
          @space padding-bottom 75px;
        }

        &[data-active] {
          display: grid;
        }

        .case-card {
          grid-area: stack;
          position: relative;
          max-width: none;
          user-select: none;
          transform: translateZ(0px);
          -webkit-transform: translateZ(0px);

          &:hover {
            img {
              transform: none;
              user-select: none;
              pointer-events: none;
            }
          }

          .reveal-tags {
            pointer-events: all;
          }

          .meta {
            opacity: 0;
            transition: opacity 0.5s ease;
          }

          &[data-active] + .case-card {
            .meta {
              @responsive >=ipad_portrait {
                opacity: 1;
              }

              .button {
                @responsive >=ipad_portrait {
                  background-color: black;
                }
              }
            }
          }

          &:nth-child(1),
          &:nth-child(2) {
            z-index: 1;
            transform: translate(0, 0);
            @space width 450px >=desktop_lg;
            @space width 350px desktop_md;
            @space width 325px ipad_landscape;
            @space width 290px ipad_portrait;
            @space width 150px $mobile;

            .cover-and-link {
              animation:
                hoverV 1.5s alternate infinite ease-in-out,
                hoverH 2.5s alternate infinite ease-in-out;
            }
          }
          &:nth-child(2) {
            z-index: 50;
            pointer-events: none;
          }

          &:nth-child(3),
          &:nth-child(4) {
            z-index: 2;
            @space width 275px >=desktop_lg;
            @space width 225px desktop_md;
            @space width 225px ipad_landscape;
            @space width 225px ipad_portrait;
            @space width 125px $mobile;
            transform: translate(-100%, 15%);

            .cover-and-link {
              animation:
                hoverV 4.5s alternate infinite ease-in-out,
                hoverH 2s alternate infinite ease-in-out;
            }
          }
          &:nth-child(4) {
            z-index: 51;
            pointer-events: none;
          }

          &:nth-child(5),
          &:nth-child(6) {
            z-index: 3;
            @space width 275px >=desktop_lg;
            @space width 225px desktop_md;
            @space width 225px ipad_landscape;
            @space width 225px ipad_portrait;
            @space width 125px $mobile;
            transform: translate(85%, -12%);

            .cover-and-link {
              animation:
                hoverV 2.5s alternate infinite ease-in-out,
                hoverH 3s alternate infinite ease-in-out;
            }
          }
          &:nth-child(6) {
            z-index: 56;
            pointer-events: none;
          }
        }
      }
    }
  }
}

